def sha(p:Path): return hashlib.sha256(p.read_bytes()).hexdigest()
def get(url,p):
    if p.exists() and p.stat().st_size:
        return p
    r=requests.get(url,timeout=180,headers={'User-Agent':'AreaData/0.10.2 source collector'});r.raise_for_status();p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(r.content);return p
def pct(n,d): return None if not d else round(n/d*100,4)

