def main():
 p=argparse.ArgumentParser();p.add_argument('--project',required=True);p.add_argument('--out',required=True);a=p.parse_args();root=Path(a.project).resolve();out=Path(a.out).resolve();out.mkdir(parents=True,exist_ok=True)
 source=root/'raw/discovered-source-files/ATG/001-Census_2011_Book_of_Statistical_Tables_I.pdf'
 if not source.exists(): get(CENSUS_URL,source)
