 meta=requests.get(GEO_META,timeout=120,headers={'User-Agent':'AreaData/0.10.2 source collector'}).json(); geo=get(meta['simplifiedGeometryGeoJSON'],raw/'geoBoundaries-ATG-ADM1_simplified.geojson'); gj=json.loads(geo.read_text(encoding='utf-8'))
 planning=[]
 for url,name in [(LAW,'physical-planning-act-2003.pdf'),(BUDGET,'budget-estimates-2026.pdf'),(STRATEGY,'budget-speech-and-development-strategy-2016.pdf'),(BARBUDA_PLAN,'future-barbuda-development-plan-vol4.pdf'),(HEALTH_PLAN,'national-health-strategy-2016-2020.pdf')]:
  planning.append(get(url,raw/name))
