 if set(names)!=expected: raise RuntimeError(f'Unexpected boundary names {set(names)^expected}')
 territories=[];features=[];ids={}
 for name in sorted(expected):
  f=names[name];props=f['properties'];tid=f"ATG:C2011:ADM1:{props['shapeISO'].split('-')[-1]}";ids[name]=tid
  territories.append({'id':tid,'country_id':'ATG','name':name,'level':'parish_dependency','type':'parish','parent_id':'ATG','official_code':props['shapeISO'],'code_system':'ISO 3166-2','boundary_version':'geoBoundaries ATG ADM1 2009 / build 2023-12-12','valid_from':'2009-01-01','geography_note':'Reference boundary. Census City and Rural rows for Saint John are combined to this parish; Redonda has no published row in the adopted Census tables.'})
  features.append({'type':'Feature','properties':{'territory_id':tid,'source_id':'atg-geoboundaries-adm1-2009','official_code':props['shapeISO'],'code_system':'ISO 3166-2','geometry_edition':'geoBoundaries ATG ADM1 2009','join_method':'Exact published parish/dependency name; Saint John Census rows summed before join','reference_only':True},'geometry':f['geometry']})
 rows={'ATG':NATIONAL,**{ids[k]:v for k,v in PARISH.items()}}
 source_id='atg-statistics-census-2011'
 specs=[
  ('ATG_C2011_POP_TOTAL','Census resident population','Population','people',lambda r:r['pop'],'sum','Total resident population; institutional population is included.'),
  ('ATG_C2011_FEMALE_PCT','Female population','Population','%',lambda r:pct(r['female'],r['pop']) if r['female'] is not None else None,'none','Female residents as a share of the resident Census population.'),
  ('ATG_C2011_HOUSEHOLDS','Non-institutional households','Households and housing','households',lambda r:r['households'],'sum','Households in the non-institutional housing tables.'),
  ('ATG_C2011_PUBLIC_WATER_PCT','Households using a public water source','Water','% of households',lambda r:pct(r['water'],r['households']) if r['water'] is not None else None,'none','Households whose main water source is public standpipe, public well/tank, or public piped supply into dwelling or yard.'),
  ('ATG_C2011_ELECTRICITY_PCT','Households using public electricity or a private generator','Basic services','% of households',lambda r:pct(r['elec'],r['households']) if r['elec'] is not None else None,'none','Households reporting public electricity or a private generator as the source of lighting.'),
  ('ATG_C2011_BATHROOM_INSIDE_PCT','Households with a bathroom inside the dwelling','Sanitation','% of households',lambda r:pct(r['bath'],r['households']) if r['bath'] is not None else None,'none','Households with a bathroom inside the dwelling. This is a bathroom-location indicator, not a sewer-connection rate.'),
  ('ATG_C2011_NO_EDUCATION_PCT','Population age 15+ with no education level','Education','% of population age 15+',lambda r:pct(r['education_none'],r['education_total']) if r['education_none'] is not None else None,'none','Population age 15 or older whose highest education level attained is none.'),
  ('ATG_C2011_UNEMPLOYMENT_RATE','Unemployment rate','Employment','% of active population',lambda r:pct(r['unemployed'],r['active']) if r['unemployed'] is not None else None,'none','Unemployed people as a share of the active population at Census Day.'),
  ('ATG_C2011_FOREIGN_BORN_PCT','Foreign-born population','Migration','% of non-institutional population',lambda r:pct(r['born_abroad'],r['born_total']) if r['born_abroad'] is not None else None,'none','People born abroad as a share of the non-institutional population with stated or unstated birthplace.'),
 ]
 indicators=[];observations=[]
 for iid,name,theme,unit,calc,aggregation,definition in specs:
  indicators.append({'id':iid,'name':name,'theme':theme,'unit':unit,'definition':definition,'definition_id':'ATG-CENSUS-2011','population':'Published 2011 Census universe stated for each table','measurement_method':'source_reported' if aggregation=='sum' else 'derived_from_source_counts','aggregation':aggregation,'period_policy':'fixed_source_period','series_family':'census','display_role':'primary','source_id':source_id,'source_locator':'2011 Census Book of Statistical Tables I: Tables 1.1a, 1.4a, 1.5a, 1.9a, 5.1, 8.2, 9.5 and 11.9'})
