  ('ATG_C2011_STJOHN_CITY_SHARE','Population in St. John City enumeration parish','Settlement','% of resident Census population',pct(22219,85567),'Residents in the published St. John City enumeration parish as a share of resident population. This is not a national urbanization rate.','2011','atg-statistics-census-2011'),
  ('ATG_HEALTH2014_CHILD_UNDERNUTRITION','Child undernutrition recorded at public clinics','Nutrition','% of children age 0-4 attending public clinics',2.9,'Children age 0-4 attending public clinics reported with undernutrition in the national health strategy.','2014','atg-national-health-strategy'),
